EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<InputProbeMode>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<FocusOperation>(enum_arg_value));
      }
    case 131: {
        return CustomEncodableValue(XInputState::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 132: {
        return CustomEncodableValue(XInputSlot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 133: {
        return CustomEncodableValue(XInputSnapshot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(FocusCommand::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(ForegroundGrantSnapshot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 136: {
        return CustomEncodableValue(FocusSnapshot::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(InputProbeMode)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<InputProbeMode>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(FocusOperation)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<FocusOperation>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(XInputState)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(std::any_cast<XInputState>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(XInputSlot)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(std::any_cast<XInputSlot>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(XInputSnapshot)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<XInputSnapshot>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(FocusCommand)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<FocusCommand>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(ForegroundGrantSnapshot)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<ForegroundGrantSnapshot>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(FocusSnapshot)) {
      stream->WriteByte(136);
      WriteValue(EncodableValue(std::any_cast<FocusSnapshot>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

