void InputProbeHostApi::SetUp(
  ::flutter::BinaryMessenger* binary_messenger,
  InputProbeHostApi* api,
  const std::string& message_channel_suffix) {
  const std::string prepended_suffix = message_channel_suffix.length() > 0 ? std::string(".") + message_channel_suffix : "";
  {
    BasicMessageChannel<> channel(binary_messenger, "dev.flutter.pigeon.mystia_steward_companion_window_probe.InputProbeHostApi.sampleXInput" + prepended_suffix, &GetCodec());
    if (api != nullptr) {
      channel.SetMessageHandler([api](const EncodableValue& message, const ::flutter::MessageReply<EncodableValue>& reply) {
        try {
          api->SampleXInput([reply](ErrorOr<XInputSnapshot>&& output) {
            if (output.has_error()) {
              reply(WrapError(output.error()));
              return;
            }
            EncodableList wrapped;
            wrapped.push_back(CustomEncodableValue(std::move(output).TakeValue()));
            reply(EncodableValue(std::move(wrapped)));
          });
        } catch (const std::exception& exception) {
          reply(WrapError(exception.what()));
        }
      });
    } else {
      channel.SetMessageHandler(nullptr);
    }
  }
  {
    BasicMessageChannel<> channel(binary_messenger, "dev.flutter.pigeon.mystia_steward_companion_window_probe.InputProbeHostApi.executeFocus" + prepended_suffix, &GetCodec());
    if (api != nullptr) {
      channel.SetMessageHandler([api](const EncodableValue& message, const ::flutter::MessageReply<EncodableValue>& reply) {
        try {
          const auto& args = std::get<EncodableList>(message);
          const auto& encodable_command_arg = args.at(0);
          if (encodable_command_arg.IsNull()) {
            reply(WrapError("command_arg unexpectedly null."));
            return;
          }
          const auto& command_arg = std::any_cast<const FocusCommand&>(std::get<CustomEncodableValue>(encodable_command_arg));
          api->ExecuteFocus(command_arg, [reply](ErrorOr<FocusSnapshot>&& output) {
            if (output.has_error()) {
              reply(WrapError(output.error()));
              return;
            }
            EncodableList wrapped;
            wrapped.push_back(CustomEncodableValue(std::move(output).TakeValue()));
            reply(EncodableValue(std::move(wrapped)));
          });
        } catch (const std::exception& exception) {
          reply(WrapError(exception.what()));
        }
      });
    } else {
      channel.SetMessageHandler(nullptr);
    }
  }
  {
    BasicMessageChannel<> channel(binary_messenger, "dev.flutter.pigeon.mystia_steward_companion_window_probe.InputProbeHostApi.finish" + prepended_suffix, &GetCodec());
    if (api != nullptr) {
      channel.SetMessageHandler([api](const EncodableValue& message, const ::flutter::MessageReply<EncodableValue>& reply) {
        try {
          const auto& args = std::get<EncodableList>(message);
          const auto& encodable_report_json_arg = args.at(0);
          if (encodable_report_json_arg.IsNull()) {
            reply(WrapError("report_json_arg unexpectedly null."));
            return;
          }
          const auto& report_json_arg = std::get<std::string>(encodable_report_json_arg);
          const auto& encodable_exit_code_arg = args.at(1);
          if (encodable_exit_code_arg.IsNull()) {
            reply(WrapError("exit_code_arg unexpectedly null."));
            return;
          }
          const int64_t exit_code_arg = encodable_exit_code_arg.LongValue();
          api->Finish(report_json_arg, exit_code_arg, [reply](std::optional<FlutterError>&& output) {
            if (output.has_value()) {
              reply(WrapError(output.value()));
              return;
            }
            EncodableList wrapped;
            wrapped.push_back(EncodableValue());
            reply(EncodableValue(std::move(wrapped)));
          });
        } catch (const std::exception& exception) {
          reply(WrapError(exception.what()));
        }
      });
    } else {
      channel.SetMessageHandler(nullptr);
    }
  }
}

EncodableValue InputProbeHostApi::WrapError(std::string_view error_message) {
  return EncodableValue(EncodableList{
    EncodableValue(std::string(error_message)),
    EncodableValue("Error"),
    EncodableValue()
  });
}

EncodableValue InputProbeHostApi::WrapError(const FlutterError& error) {
  return EncodableValue(EncodableList{
    EncodableValue(error.code()),
    EncodableValue(error.message()),
    error.details()
  });
}

